import json
import re

# Harakat regex for plain arabic strip check
TASHKEEL_REGEX = re.compile(r'[\u0617-\u061A\u064B-\u0652\u0670\u0640]')

def strip_tashkeel(text):
    return TASHKEEL_REGEX.sub('', text)

# We need at least 260 items: approx 130 words, 130 phrases.
# Topic: Batch 9: Friendly banter, mild arguments, disagreement, bargaining at the market
# (shou bak, bala fazafeez, ghali kteer, ra55isna, wallah ma bisir, etc.)

entries = []

def add_entry(arabic, arabic_plain, translit, translation_en, category):
    # Verify plain matches stripped arabic
    calc_plain = strip_tashkeel(arabic)
    if calc_plain != arabic_plain:
        print(f"Warning mismatch: {arabic} -> {calc_plain} vs {arabic_plain}")
    if len(translit) < 2:
        print(f"Warning translit count < 2: {translit}")
    entries.append({
        "arabic": arabic,
        "arabic_plain": arabic_plain,
        "translit": translit,
        "translation_en": translation_en,
        "dialect": "Levantine",
        "category": category
    })

